function [pos, vel] = cheb_state(rec, nc, et)
%CHEB_STATE  de440.chebval over one type-2 record: the Chebyshev polynomials T_i and their derivatives at the record's tau, then
%   each component's sum and its derivative over the half-length; nc coefficients a component. [km, km/s]
%   rec: real[1][DE_REC] (passed a plain number)
%   nc: int (passed a whole number)
%   et: real[1] (passed a plain number)
%   returns pos: real[1][3] (passed a plain number)
%   returns vel: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    pos = zeros(3, 1);
    vel = zeros(3, 1);
    mid = rec(1);
    radius = rec(2);
    tau = ((et - mid) / radius);
    t = zeros(20, 1);
    dt = zeros(20, 1);
    t(1) = 1;
    if (nc > 1)
        t(2) = tau;
    end
    for i = (2):((nc) - 1)
        t((i) + 1) = (((2 * tau) * t(((i - 1)) + 1)) - t(((i - 2)) + 1));
    end
    dt(1) = 0;
    if (nc > 1)
        dt(2) = 1;
    end
    if (nc > 2)
        dt(3) = (4 * tau);
    end
    for i = (3):((nc) - 1)
        dt((i) + 1) = ((((2 * tau) * dt(((i - 1)) + 1)) + (2 * t(((i - 1)) + 1))) - dt(((i - 2)) + 1));
    end
    pos = zeros(3, 1);
    vel = zeros(3, 1);
    c = ((0):((3) - 1)).';
    val = (0) .* ones(size(c));
    der = (0) .* ones(size(c));
    for i = (0):((nc) - 1)
        val = (val + (reshape(rec((((2 + (c .* nc)) + i)) + 1), [], 1) .* t((i) + 1)));
        der = (der + (reshape(rec((((2 + (c .* nc)) + i)) + 1), [], 1) .* dt((i) + 1)));
    end
    pos((c) + 1) = val;
    vel((c) + 1) = (der ./ radius);
end
